CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS characters (id uuid PRIMARY KEY,account_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,slot integer NOT NULL CHECK(slot BETWEEN 0 AND 3),name text NOT NULL,state jsonb NOT NULL,coins numeric(20,0) NOT NULL DEFAULT 200 CHECK(coins BETWEEN 0 AND 18446744073709551615),spirit numeric(20,0) NOT NULL DEFAULT 0 CHECK(spirit BETWEEN 0 AND 18446744073709551615),exp numeric(20,0) NOT NULL DEFAULT 0 CHECK(exp BETWEEN 0 AND 18446744073709551615),revision bigint NOT NULL DEFAULT 0,deleted_until timestamptz,UNIQUE(account_id,slot));
CREATE TABLE IF NOT EXISTS activity (account_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,character_id uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,epoch bigint NOT NULL DEFAULT 1,mode text NOT NULL CHECK(mode IN ('online','offline','idle')),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (hash text PRIMARY KEY,account_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,character_id uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS operations (actor uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,type text NOT NULL,request_id text NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor,type,request_id));
CREATE TABLE IF NOT EXISTS ledger (id bigserial PRIMARY KEY,actor uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,operation_type text NOT NULL,request_id text NOT NULL,before_coins numeric(20,0) NOT NULL,after_coins numeric(20,0) NOT NULL,before_spirit numeric(20,0) NOT NULL,after_spirit numeric(20,0) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id bigserial PRIMARY KEY,actor uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market (id uuid PRIMARY KEY,account_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,seller uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,item jsonb NOT NULL,price numeric(20,0) NOT NULL CHECK(price BETWEEN 1 AND 18446744073709551615),status text NOT NULL DEFAULT 'active',expires_at timestamptz NOT NULL,buyer uuid REFERENCES characters(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS offline_jobs (id uuid PRIMARY KEY,character_id uuid NOT NULL UNIQUE REFERENCES characters(id) ON DELETE CASCADE,epoch bigint NOT NULL,started_at timestamptz NOT NULL,ended_at timestamptz,plan jsonb NOT NULL,report jsonb,settled boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS market_active ON market(status,expires_at);
